#!/usr/bin/env python3
"""
Citation reference table generator.
Scans [CITE:xxx] placeholders, assigns numbers by first-appearance order,
and outputs a formatted reference table using rich.

Usage:
    python cite_table.py <input_file>
"""

import re
import sys
import os
from collections import OrderedDict

from rich.console import Console
from rich.table import Table
from rich.text import Text

PLACEHOLDER_RE = re.compile(r'\[CITE:([a-zA-Z0-9_\-]+)\]')
DISCLAIMER = (
    'This table was generated by a hard-coded script (cite_table.py). '
    'No LLM involvement — all citations trace back to real placeholders '
    'in the source text.'
)


def scan_order(text):
    seen = OrderedDict()
    for match in PLACEHOLDER_RE.finditer(text):
        key = match.group(1)
        if key not in seen:
            seen[key] = len(seen) + 1
    return seen


def extract_context(text, start, end, max_len=50):
    before = text[:start]
    after = text[end:]

    sent_start = 0
    for sep in ['. ', '.\n', '! ', '?\n', '!\n', '?\n']:
        idx = before.rfind(sep)
        if idx > sent_start:
            sent_start = idx + len(sep)

    sent_end = len(text)
    for sep in ['. ', '.\n', '! ', '? ', '!\n', '?\n']:
        idx = after.find(sep)
        if idx != -1 and idx + end < sent_end:
            sent_end = idx + end + 1
            break

    sentence = text[sent_start:sent_end].replace('\n', ' ').strip()
    if len(sentence) > max_len:
        sentence = sentence[:max_len - 3] + '...'
    return sentence


def format_author(key):
    name = re.split(r'\d', key)[0]
    if name and name[0].islower():
        name = name[0].upper() + name[1:]
    return name


def main():
    console = Console()

    if len(sys.argv) > 1:
        with open(sys.argv[1], 'r', encoding='utf-8') as f:
            text = f.read()
    else:
        text = sys.stdin.read()

    placeholders = scan_order(text)
    mapping = {k: placeholders[k] for k in placeholders}

    num_hdr = '#'
    author_hdr = 'Author'
    ctx_hdr = 'Context (50 chars)'
    status_hdr = 'Status'
    status_ok = 'OK'
    status_reuse = 'Reuse'
    status_bad = 'Bad Order'
    title = 'Reference Table'

    # Build flat list of all occurrences with context
    occurrences = []
    for match in PLACEHOLDER_RE.finditer(text):
        key = match.group(1)
        num = mapping[key]
        ctx = extract_context(text, match.start(), match.end())
        ctx = ctx.replace(f'[CITE:{key}]', f'[{num}]')
        occurrences.append({'num': num, 'key': key, 'context': ctx})

    # Determine status for each occurrence
    key_first_seen = {}
    for occ in occurrences:
        key = occ['key']
        if key not in key_first_seen:
            key_first_seen[key] = True
            occ['status'] = status_ok
        else:
            occ['status'] = status_reuse

    # Print disclaimer
    console.print()
    console.print(f'[dim]{DISCLAIMER}[/]')
    console.print()

    table = Table(
        title=f'[bold]{title}[/]',
        border_style='bright_black',
        show_lines=True,
    )
    table.add_column(num_hdr, style='cyan', width=6)
    table.add_column(author_hdr, style='yellow', width=16)
    table.add_column(ctx_hdr, style='white', width=52)
    table.add_column(status_hdr, style='green', width=12)

    seen = set()
    for occ in occurrences:
        key = occ['key']
        if key in seen:
            continue
        seen.add(key)
        num_str = str(occ['num'])
        table.add_row(
            Text(num_str, style='cyan'),
            Text(format_author(key), style='yellow'),
            Text(occ['context']),
            Text(occ['status'], style='green'),
        )

    console.print(table)
    console.print(f'[dim]{len(seen)} references total.[/]')


if __name__ == '__main__':
    main()
